function heat(m,c,dT){ return m*c*dT; }
function phase(m,L){ return m*L; }
function mixTemp(m1,c1,T1,m2,c2,T2){ var den=m1*c1+m2*c2; if(den===0) return null; return (m1*c1*T1+m2*c2*T2)/den; }
var EXPORTS={heat:heat, phase:phase, mixTemp:mixTemp};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HeatForgePure = EXPORTS; }
